class ConfigError(ValueError):
    pass


def validate_config(config: SoloMatchConfig, known_maps: tuple[str, ...]) -> None:
    """Raise ConfigError for a request the server cannot run."""
    if config.mode not in SUPPORTED_MODES:
        raise ConfigError(f"Unsupported mode {config.mode!r}")
    if config.map_id not in known_maps:
        raise ConfigError(f"Unknown map {config.map_id!r}")
    if config.bot_difficulty not in DIFFICULTIES:
        raise ConfigError(f"Unknown bot difficulty {config.bot_difficulty!r}")
    if config.real_players < 1:
        raise ConfigError("A solo match needs a human player")
    if config.bot_count < 0:
        raise ConfigError("Bot count cannot be negative")
    if config.total_players > config.max_players:
        raise ConfigError("Too many participants for the match")
    if not 1 <= config.tick_rate <= 60:
        raise ConfigError("Invalid tick rate")
    if config.warmup_seconds < 0:
        raise ConfigError("Warmup cannot be negative")
    if not config.zone_phases:
        raise ConfigError("At least one zone phase is required")
    if not (config.client_landing_timeout > 0 and config.client_landing_timeout < float("inf")):
        raise ConfigError("Client landing timeout must be positive and finite")
